(()=>{'use strict';if(window.__qmesIqcPurchaseImport)return;window.__qmesIqcPurchaseImport=true;
const $=(s,r=document)=>r.querySelector(s);
const date=v=>{const x=String(v||'').match(/(20\d{2})[-./년\s]+(\d{1,2})[-./월\s]+(\d{1,2})/);if(!x)return '';const d=new Date(Date.UTC(+x[1],+x[2]-1,+x[3]));return d.getUTCFullYear()===+x[1]&&d.getUTCMonth()===+x[2]-1&&d.getUTCDate()===+x[3]?d.toISOString().slice(0,10):''};
const minus7=d=>{const x=new Date(d+'T12:00:00Z');x.setUTCDate(x.getUTCDate()-7);return x.toISOString().slice(0,10)};
const pick=(r,...keys)=>{for(const k of keys){const v=r?.[k];if(v!==undefined&&v!==null&&String(v).trim()!=='')return String(v).trim()}return ''};
const unwrap=x=>{let p=x?.payload||x; if(typeof p==='string'){try{p=JSON.parse(p)}catch{return {}}}return p||{}};
const parseQty=v=>{const n=Number(String(v||'').replace(/,/g,'').match(/\d+(?:\.\d+)?/)?.[0]);return Number.isFinite(n)&&n>0?n:0};
const keyOf=r=>[r.date,r.supplier,r.item,r.lot,r.qty].join('|');
let entries=[], existing=new Set(),busy=false;
function read(r){const p=unwrap(r);const x=p?.data&&typeof p.data==='object'?p.data:p;const inspectionDate=date(pick(x,'inspectionDate','inspection_date','testDate','receiveDate','receiptDate','date','검사일자','검사일','입고일자','입고일'));return {date:inspectionDate,supplier:pick(x,'supplier','vendor','supplierName','company','companyName','거래처','공급업체'),item:pick(x,'item','material','materialName','itemName','productName','품목명','원자재명'),qty:parseQty(pick(x,'qty','quantity','receiptQty','receiveQty','receivedQty','weight','수량','입고수량')),lot:pick(x,'lot','lotNo','materialLot','LOT','LOT NO'),unit:pick(x,'unit','단위')||'kg',result:pick(x,'judge','inspectionResult','result','status','판정')}}
async function json(url,opts){const r=await fetch(url,{credentials:'include',cache:'no-store',...opts});const x=await r.json();if(!r.ok||x?.success===false||x?.ok===false)throw Error(x?.message||'HTTP '+r.status);return x}
const rows=x=>Array.isArray(x)?x:Array.isArray(x?.data)?x.data:Array.isArray(x?.rows)?x.rows:[];
function notice(s){const el=$('#qpu-import-feedback');if(el)el.textContent=s}
function show(){const body=$('#qpu-import-body');if(!body)return;body.replaceChildren();entries.forEach((e,i)=>{const tr=document.createElement('tr');const valid=Boolean(e.date&&e.supplier&&e.item&&e.qty);const fields=[String(i+1),e.supplier||'미확인',e.item||'미확인',e.qty||'미확인',e.date?minus7(e.date):'미확인',e.date||'미확인',e.lot||'—',valid?'등록 대기':'필수정보 부족'];for(const f of fields){const td=document.createElement('td');td.textContent=f;tr.append(td)}if(!valid)tr.style.background='#fff2f2';body.append(tr)});notice(entries.length+'건 조회 · 필수 항목을 확인하고 등록하세요. 원본 수입검사 기록은 변경되지 않습니다.')}
async function load(){notice('수입검사 데이터 확인 중…');try{const [raw,po]=await Promise.all([json('/api/qmes-sync/iqc'),json('/api/purchase-orders')]);const dedup=new Set();existing=new Set(rows(po).map(p=>[p.supplier,p.item,p.requestedDueDate||p.due,p.qty,p.materialLot||p.lot||''].join('|')));entries=rows(raw).map(read).filter(r=>r.date||r.supplier||r.item).filter(r=>{const k=keyOf(r);if(dedup.has(k))return false;dedup.add(k);return true});show()}catch(e){notice('자료를 가져오지 못했습니다: '+e.message+' (권한과 서버 연결을 확인해 주세요.)')}}
function make(){let dlg=$('#qpu-import-dialog');if(dlg)return dlg;dlg=document.createElement('div');dlg.id='qpu-import-dialog';dlg.hidden=true;dlg.innerHTML='<div class="qpi-panel"><header><strong>수입검사 → 구매발주 등록 확인</strong><button type="button" class="qpi-close">×</button></header><p>발주일자: 수입검사일 7일 전 · 요청입고일: 검사 당일 · 발주상태/IQC: 완료. 발주번호는 PO-YYYYMMDD-001 형식이며 중복 시 다음 번호를 사용합니다.</p><div class="qpi-scroll"><table><thead><tr><th>NO</th><th>공급업체</th><th>품목명</th><th>수량</th><th>발주일자</th><th>요청입고일</th><th>LOT</th><th>검토</th></tr></thead><tbody id="qpu-import-body"></tbody></table></div><div id="qpu-import-feedback" aria-live="polite"></div><footer><button type="button" class="qpi-cancel">취소</button><button type="button" class="qpi-save">확인 후 등록</button></footer></div>';document.body.append(dlg);$('.qpi-close',dlg).onclick=$('.qpi-cancel',dlg).onclick=()=>dlg.hidden=true;$('.qpi-save',dlg).onclick=save;return dlg}
async function save(){if(busy)return;const good=entries.filter(x=>x.date&&x.supplier&&x.item&&x.qty);if(!good.length){notice('등록 가능한 필수정보가 없습니다.');return}if(!window.confirm(good.length+'건의 수입검사 자료를 실제 구매발주로 등록하시겠습니까? 기존 발주는 변경하지 않습니다.'))return;busy=true;const btn=$('.qpi-save');btn.disabled=true;let done=0,skip=0,fail=0;try{const r=rows(await json('/api/purchase-orders'));const taken=new Set(r.map(x=>x.purchaseNo||x.no||x.id));const seen=new Set(r.map(p=>[p.supplier,p.item,p.requestedDueDate||p.due,p.qty,p.materialLot||p.lot||''].join('|')));for(const x of good){const identity=[x.supplier,x.item,x.date,x.qty,x.lot].join('|');if(seen.has(identity)){skip++;continue}const d=minus7(x.date),prefix='PO-'+d.replace(/-/g,'')+'-';let n=1;while(taken.has(prefix+String(n).padStart(3,'0')))n++;const no=prefix+String(n).padStart(3,'0');const payload={purchaseNo:no,purchaseType:'수입검사 연계',supplier:x.supplier,item:x.item,qty:x.qty,unit:x.unit,orderDate:d,requestedDueDate:x.date,confirmedDueDate:x.date,receiptDate:x.date,receivedQty:x.qty,receiptStatus:'입고완료',status:'완료',iqcStatus:'완료',materialLot:x.lot,notes:'수입검사 자료에서 사용자 확인 후 등록 (검사일: '+x.date+')'};try{await json('/api/purchase-orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});done++;taken.add(no);seen.add(identity)}catch(e){fail++;notice('등록 중 오류: '+e.message)}}notice('등록 완료 '+done+'건 / 중복 제외 '+skip+'건 / 실패 '+fail+'건. 성공 건만 실제 저장되었습니다.')}catch(e){notice('구매발주 확인 오류: '+e.message)}finally{busy=false;btn.disabled=false}}
function init(){const p=$('#purchase');const toolbar=$('.module-toolbar',p);if(!toolbar||$('#qpu-import-btn',p))return;const b=document.createElement('button');b.type='button';b.id='qpu-import-btn';b.className='btn';b.textContent='수입검사 가져오기';b.onclick=()=>{make().hidden=false;load()};const tools=$('.table-tools',toolbar);if(tools)tools.prepend(b)}
const style=document.createElement('style');style.textContent='#qpu-import-dialog[hidden]{display:none}#qpu-import-dialog{position:fixed;inset:0;z-index:9999;background:#12233b66;display:flex;align-items:center;justify-content:center;padding:20px}#qpu-import-dialog .qpi-panel{background:white;border-radius:10px;width:min(1100px,95vw);max-height:85vh;display:flex;flex-direction:column;box-shadow:0 20px 60px #14243c44;color:#233e5c}#qpu-import-dialog header,#qpu-import-dialog footer{padding:15px 20px;display:flex;justify-content:space-between;align-items:center;background:#edf3f9}#qpu-import-dialog p{padding:8px 20px;font-size:12px}#qpu-import-dialog .qpi-scroll{overflow:auto;min-height:120px;max-height:55vh}#qpu-import-dialog table{border-collapse:collapse;width:100%;font-size:12px}#qpu-import-dialog th,#qpu-import-dialog td{border:1px solid #d4e0ed;padding:9px;white-space:nowrap}#qpu-import-dialog th{background:#e5eef8}#qpu-import-feedback{padding:12px 20px;font-size:12px}#qpu-import-dialog button{border:1px solid #c9d7e7;background:#fff;border-radius:6px;padding:8px 12px;cursor:pointer}#qpu-import-dialog .qpi-save{background:#166fbb;color:#fff;margin-left:8px}#qpu-import-btn{white-space:nowrap}';document.head.append(style);new MutationObserver(init).observe(document.body,{childList:true,subtree:true});init();
})();